<script setup>
defineProps({ caseRecord:{ type:Object, default:null }, runs:{ type:Array, default:() => [] }, documents:{ type:Array, default:() => [] }, loading:Boolean, error:{ type:String, default:'' } })
defineEmits(['retry','back','continue-case'])
function date(value) { const parsed = new Date(value); return value && !Number.isNaN(parsed.getTime()) ? new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(parsed) : 'Fecha no disponible' }
function toolName(tool) { return ({case:'NovaCase',court:'NovaCourt',search:'NovaSearch'})[tool] || 'Análisis' }
function historicalLink(run, caseId) { return `/?tool=${encodeURIComponent(run.tool)}&case_id=${encodeURIComponent(caseId)}&run_id=${encodeURIComponent(run.id)}` }
</script>

<template>
  <section class="case-detail" aria-labelledby="case-detail-title">
    <button class="back-link" type="button" @click="$emit('back')">← <span>Mis casos</span></button>
    <div v-if="loading" class="detail-loading" role="status">Cargando la información del caso…</div>
    <div v-else-if="error" class="detail-error" role="alert"><h1>No fue posible abrir el caso</h1><p>{{ error }}</p><button type="button" @click="$emit('retry')">Reintentar</button></div>
    <div v-else-if="caseRecord" class="detail-content">
      <header class="detail-heading"><div><p class="page-kicker">EXPEDIENTE</p><h1 id="case-detail-title">{{ caseRecord.title || 'Caso jurídico' }}</h1><p>{{ caseRecord.description || 'Información y actividad guardadas para este caso.' }}</p></div><button class="primary-action" type="button" @click="$emit('continue-case', caseRecord)">Continuar en NovaCase</button></header>
      <div class="detail-columns">
        <section class="detail-section" aria-labelledby="documents-title"><header><div><p class="page-kicker">ARCHIVO DEL CASO</p><h2 id="documents-title">Documentos</h2></div><span class="section-count">{{ documents.length }}</span></header>
          <p v-if="!documents.length" class="section-empty">No hay documentos disponibles para este caso.</p>
          <ul v-else class="document-list"><li v-for="(document,index) in documents" :key="document.document_id || document.id || document.filename || index"><span class="document-type" aria-hidden="true">{{ (document.filename || document.original_filename || 'DOC').split('.').pop().slice(0,4).toUpperCase() }}</span><span class="document-copy"><strong>{{ document.original_filename || document.filename || document.name || 'Documento del caso' }}</strong><small>{{ document.processing_status || document.status || 'Asociado al caso' }}</small></span></li></ul>
        </section>
        <section class="detail-section" aria-labelledby="runs-title"><header><div><p class="page-kicker">ACTIVIDAD</p><h2 id="runs-title">Historial de análisis</h2></div><span class="section-count">{{ runs.length }}</span></header>
          <p v-if="!runs.length" class="section-empty">Aún no hay análisis guardados para este caso.</p>
          <ol v-else class="run-list"><li v-for="run in runs" :key="run.id"><div class="run-marker" aria-hidden="true"></div><div class="run-copy"><strong>{{ toolName(run.tool) }}</strong><span class="run-status">{{ run.status === 'completed' ? 'Completado' : run.status === 'partial' ? 'Parcial' : run.status === 'processing' ? 'En curso' : run.status === 'failed' ? 'No completado' : run.status === 'cancelled' ? 'Cancelado' : 'En espera' }}</span><small>{{ date(run.created_at || run.started_at) }}</small></div><a v-if="['case','court'].includes(run.tool) && ['completed','partial'].includes(run.status)" :href="historicalLink(run,caseRecord.id)" :aria-label="`Abrir ejecución histórica de ${toolName(run.tool)}`">Abrir →</a></li></ol>
        </section>
      </div>
    </div>
  </section>
</template>

<style scoped>
