 li{display:flex;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid #edf0f1}.document-list li:last-child,.run-list li:last-child{border-bottom:0}.document-type{display:grid;place-items:center;flex:none;width:39px;height:39px;border-radius:7px;background:#edf2f3;color:#426176;font-size:9px;font-weight:700}.document-copy,.run-copy{display:grid;gap:4px;min-width:0}.document-copy strong,.run-copy strong{overflow-wrap:anywhere;color:#263f57;font-size:13px}.document-copy small,.run-copy small{color:#758494;font-size:11px}.run-list li{position:relative;display:flex;align-items:center;gap:13px;padding:15px 0;border-bottom:1px solid #edf0f1}.run-marker{flex:none;width:9px;height:9px;border-radius:50%;background:#b89b6b;box-shadow:0 0 0 4px #f1ece3}.run-copy{flex:1}.run-status{color:#50697c;font-size:11px}.run-list a{color:#254d6b;text-decoration:none;font-size:12px;font-weight:700}.run-list a:hover{text-decoration:underline}.run-list a:focus-visible{outline:2px solid #b68a3a;outline-offset:3px}@media(max-width:780px){.detail-heading{align-items:flex-start;flex-direction:column}.detail-columns{grid-template-columns:1fr}}
</style>
